					"TITSPLABST",
					"TITSP",
					"TITTXTSP",
					"TIT_RHTI"
				]
			}
		}
	]
}`

 3. Search for completion of "Notbrem" in contexts FIELD TITSPLABST (TITSPLABST is just a name from the Java context)
 This search produces no result

`POST suggest_test/_search?pretty
{
    "suggest": {
        "hfdb-suggest" : {
            "prefix" : "Notbrem", 
            "completion" : { 
                "field" : "SUGGEST" ,"skip_duplicates":false,"contexts":{
          "FIELD":[{"context":"TITSPLABST","boost":1}]
        }
            }
        }
    }
}`



4. Now search for "Notbrem" in contexts FFIELD DESKT
This search produces a result

`POST suggest_test/_search?pretty
{
    "suggest": {
        "hfdb-suggest" : {
            "prefix" : "Notbrem", 
            "completion" : { 
                "field" : "SUGGEST" ,"skip_duplicates":false,"contexts":{
          "FIELD":[{"context":"DESKT","boost":1}]
        }
            }
        }
    }
}`

I expect a result in both queries, but only got one in the second.


